CREATE DATABASE IF NOT EXISTS myfit CHARACTER SET utf8mb4;
USE myfit;
DROP TABLE IF EXISTS habit_logs,habits,activities,settings,users;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,pass_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE activities(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,type ENUM('walking','workout','yoga') NOT NULL,name VARCHAR(100) NOT NULL,duration_sec INT NOT NULL,steps INT NOT NULL DEFAULT 0,act_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,act_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE habits(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,name VARCHAR(100) NOT NULL,remind_time TIME NULL,is_manual TINYINT DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE habit_logs(habit_id INT NOT NULL,log_date DATE NOT NULL,PRIMARY KEY(habit_id,log_date),FOREIGN KEY(habit_id) REFERENCES habits(id) ON DELETE CASCADE);
CREATE TABLE settings(user_id INT NOT NULL,k VARCHAR(30) NOT NULL,v VARCHAR(30) NOT NULL,PRIMARY KEY(user_id,k),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
